@st.fragment
def cm_kotoba_audio_bridge():
    widget_key = 'cm_kotoba_audio_bridge'
    request = st.session_state.get(widget_key)
    profile = st.session_state.get('cm_profile')
    response = st.session_state.get('cm_kotoba_audio_poll_response')
    if isinstance(request, dict) and profile:
        request_id = request.get('request_id')
        ticket = request.get('ticket')
        nonce = request.get('nonce')
        if (isinstance(request_id, str) and re.fullmatch(r'[a-f0-9-]{36}', request_id)
                and isinstance(ticket, str) and re.fullmatch(r'[A-Za-z0-9_-]{43}', ticket)
                and isinstance(nonce, str) and re.fullmatch(r'[a-f0-9-]{36}', nonce)
                and (not response or (response['id'], response['_profile']) != (request_id, profile))):
            ticket_hash = hashlib.sha256(ticket.encode()).hexdigest()
            response = {'id': request_id, '_profile': profile, 'status': 'waiting'}
            try:
                url, key = cm_service_config()
                filters = {
                    'select': 'kotoba_audio', 'ticket_hash': 'eq.' + ticket_hash,
                    'profile_id': 'eq.' + profile, 'source_app': 'eq.kotoba', 'used_at': 'not.is.null',
                    'plan_item_id': 'not.is.null', 'expires_at': 'gt.' + datetime.now(timezone.utc).isoformat(),
                    'limit': '1',
                }
                outcome = request.get('outcome')
                if outcome in ('ended', 'failed'):
                    outcome_filters = {k: v for k, v in filters.items() if k not in ('select', 'limit')}
                    outcome_filters.update({'kotoba_audio->>nonce': 'eq.' + nonce, 'kotoba_audio->>status': 'eq.ready'})
                    cm_api_request(url, 'PATCH', '/rest/v1/chokomana_launch_tickets', key=key, timeout=3,
                                   params=outcome_filters, payload={'kotoba_audio': {'nonce': nonce, 'status': outcome}})
                    response['status'] = outcome
                    rows = []
                else:
                    rows = cm_api_request(url, 'GET', '/rest/v1/chokomana_launch_tickets', key=key, timeout=3, params=filters)
                audio = rows[0]['kotoba_audio'] if rows else None
                if isinstance(audio, dict) and audio.get('nonce') == nonce:
                    response.update(status=audio['status'], parts=audio.get('parts'), settings=audio.get('settings'))
            except Exception:
                response['status'] = 'error'
            stage = (nonce, response['status'])
            if st.session_state.get('cm_kotoba_audio_last_status') != stage:
                st.session_state['cm_kotoba_audio_last_status'] = stage
                cm_diag_record('audio', 'kotoba_launch', trace_id=ticket_hash[:16],
                               stage='server_relay', status=response['status'])
            st.session_state['cm_kotoba_audio_poll_response'] = response
    result = {k: v for k, v in response.items() if k != '_profile'} if response and response['_profile'] == profile else None
    cm_auth_component(CM_KOTOBA_AUDIO_BRIDGE)(audio_response=result, key=widget_key, default=None)


def cm_diag_bridge(show_download=False):
    d = cm_diag_state()
    settings = show_download
    snapshot = d['records'] if settings else d['records'][-80:]
    cm_auth_component(cm_diag_html())(key='cm_diagnostics_download' if settings else 'cm_diagnostics_bridge',
        server_records=snapshot, server_dropped=d['dropped'], controls=d['controls'],
        show_download=settings, page=cm_diag_page(),
        app_version='49', default=None)
    if not settings and st.session_state.get('cm_profile'):
        cm_kotoba_audio_bridge()



def cm_diag_run(function):
    from functools import wraps
    import time
    @wraps(function)
    def run(*args,**kwargs):
        began=time.perf_counter()
        st.session_state['cm_diag_rendering_full'] = True
        try:
            result=function(*args,**kwargs)
        except Exception as exc:
            cm_diag_record('unhandled_error','app',status='error',error=exc)
            st.session_state['cm_diag_rendering_full'] = False
            cm_diag_mark_ready(); cm_diag_bridge()
            raise
        else:
            st.session_state['cm_diag_rendering_full'] = False
            cm_diag_record('render','app',duration_ms=(time.perf_counter()-began)*1000,
                           page=cm_diag_page())
            cm_diag_mark_ready(); cm_diag_bridge()
            return result
        finally:
            st.session_state['cm_diag_rendering_full'] = False
    return run


def now_jst() -> datetime:
    return datetime.now(TOKYO)


def _setting(name: str, default: str = "") -> str:
    """Read Streamlit Secrets (or deployment environment), never render key values."""
    try:
        val = st.secrets.get(name)
    except Exception:
        val = None
    if val is None:
        val = os.environ.get(name, default)
    value = str(val or "").strip()
    return value or {
        "ENGLISH_APP_URL": DEFAULT_ENGLISH_APP_URL,
        "MOJI_APP_URL": DEFAULT_MOJI_APP_URL,
        "GEOGRAPHY_APP_URL": DEFAULT_GEOGRAPHY_APP_URL,
    }.get(name, "")


def _valid_https_url(value: str) -> bool:
    try:
        parsed = urlparse(value)
        return (parsed.scheme == "https" and bool(parsed.hostname)
                and parsed.username is None and parsed.password is None)
    except ValueError:
        return False


def _db_config() -> tuple[str, str, str, list[str]]:
    """Read only the profile verified from this browser's possession token."""
    profile = st.session_state.get("cm_profile", "")
    try:
        url, key = cm_service_config()
    except RuntimeError:
        return "", "", profile, ["SUPABASE_URL / SUPABASE_SECRET_KEY"]
    missing = [] if profile else ["利用者の自動連携"]
    return url, key, profile, missing


def fetch_day(url: str, public_key: str, profile_id: str, target_day: date, access_token: str = "") -> tuple[list[dict], bool]:
    """Fetch only one learner/day, with server-only authentication and paging.

    study_date is a generated JST date in PostgreSQL. No new rows are written.
    """
    if not _valid_https_url(url) or not public_key or not profile_id:
        raise ValueError("Supabase接続設定または学習者IDがありません")
    rows = []
    base = url.rstrip("/") + "/rest/v1/" + TABLE_NAME
    headers = {
        "apikey": public_key,
        "Accept": "application/json",
        "User-Agent": "chokomana-hub/2.0",
    }

    if profile_id != st.session_state.get("cm_profile"):
        raise ValueError("利用者の連携を確認できません")
    if not public_key.startswith("sb_secret_"):
        headers["Authorization"] = "Bearer " + public_key
    offset = 0
    truncated = False
    while offset < MAX_STAMPS_PER_DAY:
        page_size = min(BATCH_SIZE, MAX_STAMPS_PER_DAY - offset)
        params = urlencode({
            "select": ",".join(FIELDS),
            "profile_id": "eq." + profile_id,
            "study_date": "eq." + target_day.isoformat(),
            "order": "finished_at.asc,stamp_id.asc",
            "limit": str(page_size),
            "offset": str(offset),
        })
        req = Request(base + "?" + params, headers=headers, method="GET")
        try:
            with urlopen(req, timeout=9) as resp:
                batch = json.loads(resp.read().decode("utf-8"))
        except HTTPError as exc:
            cm_diag_http_error(exc, 'fetch_day')
            # Never surface the full response body or credentials to a user.
            raise RuntimeError(f"Supabaseから取得できませんでした（HTTP {exc.code}）") from None
        except (URLError, TimeoutError, OSError) as exc:
            cm_diag_record('network_error','fetch_day',status='error',error=exc)
            raise RuntimeError("Supabaseへの通信に失敗しました。接続設定をご確認ください。") from None
        except (ValueError, UnicodeError, json.JSONDecodeError):
            raise RuntimeError("Supabaseからのデータ形式を確認できませんでした。") from None
        if not isinstance(batch, list):
            raise RuntimeError("スタンプの取得形式が不正です。")
        rows.extend(x for x in batch if isinstance(x, dict))
        if len(batch) < page_size:
            break
        offset += len(batch)
    else:
        truncated = True
    try:
        speech_stamp = cm_speech_stamp_for_day(profile_id, target_day)
    except RuntimeError:
        # The regular stamp book stays available if the optional award store is down.
        speech_stamp = None
    if speech_stamp:
        rows.append(speech_stamp)
        rows.sort(key=lambda row: cm_plan_date(row.get("finished_at")) or datetime.min.replace(tzinfo=timezone.utc))
    return rows, truncated


def cm_speech_text(value):
    import unicodedata

    value = unicodedata.normalize("NFKC", value)
    value = "".join(chr(ord(c)-96) if "ァ" <= c <= "ヶ" else c for c in value)
    value = "".join(c for c in value if c != "ー" and not c.isspace()
                    and not unicodedata.category(c).startswith("P"))
    return value.removesuffix("です") if len(value) > 2 else value


def cm_medal_speech_kana(value):
    import unicodedata

    value = "".join(c for c in unicodedata.normalize("NFD", value) if c not in "\u3099\u309aー")
    return value.translate(str.maketrans("ぁぃぅぇぉっゃゅょゎ", "あいうえおつやゆよわ"))


def cm_medal_speech_close(expected, heard):
    expected, heard = cm_medal_speech_kana(expected), cm_medal_speech_kana(heard)
    if not re.fullmatch(r"[ぁ-ゖ]+", expected) or not re.fullmatch(r"[ぁ-ゖ]+", heard):
        return False
    if len(expected) == len(heard):
        errors = sum(a != b for a, b in zip(expected, heard))
        return errors <= (1 if len(expected) >= 2 else 0)
    shorter, longer = sorted((expected, heard), key=len)
    return len(longer) == len(shorter) + 1 and any(
        longer[:i] + longer[i+1:] == shorter for i in range(len(longer)))


def cm_speech_stamp(row):
    return {
        **row, "source_app": "speech", "attempt_id": row["stamp_id"],
        "category_label": "しゃべるメダル", "stamp_char": "話", "reading": "はなす",
        "grade": "gold", "correct_count": 1, "total_count": 1,
    }


def cm_speech_stamp_for_day(profile, target_day):
    rows = cm_account_request("GET", CM_SPEECH_MEDALS, params={
        "profile_id": "eq." + profile, "study_date": "eq." + target_day.isoformat(),
        "select": "stamp_id,profile_id,study_date,finished_at", "limit": "1",
    })
    return cm_speech_stamp(rows[0]) if rows else None


def cm_medal_speech_spellings(item):
    reading = cm_speech_text(item["reading"])
    return {reading, cm_speech_text(item["char"]), *(
        cm_speech_text(word) for word in CM_MEDAL_SPEECH_SPELLINGS.get(reading, "").split())}


def cm_medal_speech_matches(items, part, candidates):
    if not isinstance(candidates, list):
        return False
    item = items[part]
    reading = cm_speech_text(item["reading"])
    spellings = cm_medal_speech_spellings(item)
    others = set().union(*(cm_medal_speech_spellings(other) for other in items
                           if cm_speech_text(other["reading"]) != reading))
    recognized = [cm_speech_text(value) for value in candidates[:5]
                  if isinstance(value, str) and 0 < len(value) <= 120]
    wrong_order = others - spellings
    if recognized and recognized[0] in wrong_order:
        return False
    return any(heard and heard not in wrong_order
               and (heard in spellings or cm_medal_speech_close(reading, heard)) for heard in recognized)


def cm_award_speech_medal(profile, target_day):
    now = now_jst()
    if profile != st.session_state.get("cm_profile") or now.date() != target_day:
        return None, "ひづけが かわったよ。「今日の成果」を ひらきなおしてね。"
    rows = cm_account_request("POST", CM_SPEECH_MEDALS, {
        "profile_id": profile, "study_date": target_day.isoformat(), "finished_at": now.isoformat(),
    }, {"on_conflict": "profile_id,study_date"}, "resolution=ignore-duplicates,return=representation")
    if rows:
        return cm_speech_stamp(rows[0]), "やったね！ しゃべるメダルを かくとく！"
    stamp = cm_speech_stamp_for_day(profile, target_day)
    if not stamp:
        raise RuntimeError("speech award could not be confirmed")
    return stamp, "きょうの「しゃべるメダル」は かくとくずみ！"


def safe_int(value, fallback: int = 0) -> int:
    try:
        return int(value)
    except (TypeError, ValueError, OverflowError):
        return fallback


def jst_time(iso_value) -> str:
    if not iso_value:
        return "--:--"
    try:
        source = str(iso_value).replace("Z", "+00:00")
        dt = datetime.fromisoformat(source)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(TOKYO).strftime("%H:%M")
    except (ValueError, TypeError):
        return "--:--"


def date_label(day: date) -> str:
    weekday = "月火水木金土日"[day.weekday()]
    return f"{day.year}年{day.month}月{day.day}日（{weekday}）"


def normalize_grade(value: object) -> str:
    return str(value) if value in GRADE_NAMES else "white"


