def cm_support_prefetch(groups):
    """Fetch visible card stamps together instead of one request per target type."""
    profile=st.session_state.get('cm_profile')
    if not profile:return
    cache=st.session_state.setdefault('cm_support_cache',{});pending=[]
    for kind,values in groups.items():
        keys=tuple(sorted({str(k) for k in values if k}))
        if not keys:continue
        cache_key=(profile,kind,keys);cached=cache.get(cache_key)
        if cached and time.time()-cached['at']<30:continue
        pending.append((kind,keys,cache_key))
    if not pending:return
    rows=[]
    # Keep URL lengths bounded while combining plan/menu/attempt lookups.
    targets=[(kind,k) for kind,keys,_ in pending for k in keys]
    for offset in range(0,len(targets),40):
        clauses=[]
        for kind in sorted({t[0] for t in targets[offset:offset+40]}):
            values=','.join('"'+k.replace('\\','\\\\').replace('"','\\"')+'"'
                for t,k in targets[offset:offset+40] if t==kind)
            clauses.append('and(target_type.eq.'+kind+',target_key.in.('+values+'))')
        params={'profile_id':'eq.'+profile,'or':'('+','.join(clauses)+')',
            'select':'id,target_type,target_key,source_app,stamp_key,created_at,supporter:cm_watch_supporters(name,color)',
            'order':'created_at.desc,id','limit':'500'}
        for page in range(0,100000,500):
            part=cm_account_request('GET','/rest/v1/cm_watch_encouragements',params={**params,'offset':str(page)})
            if not isinstance(part,list):raise RuntimeError('invalid stamp response')
            rows.extend(part)
            if len(part)<500:break
        else:raise RuntimeError('stamp pagination limit reached')
    if len(cache)>60:cache.clear()
    at=time.time()
    for kind,keys,cache_key in pending:
        cache[cache_key]={'at':at,'rows':[r for r in rows if r.get('target_type')==kind and r.get('target_key') in keys]}


def cm_support_rows(kind, keys):
    keys=tuple(sorted({str(k) for k in keys if k}));profile=st.session_state.get('cm_profile')
    if not profile or not keys:return []
    cm_support_prefetch({kind:keys})
    return st.session_state['cm_support_cache'][(profile,kind,keys)]['rows']

